    { id = 4061, name = "The Rise of the Machines (1/3)", level = 54, minLevel = 52, faction = "Horde", giver = "Hierophant Theodora Mulvadania", start = { npc = "Hierophant Theodora Mulvadania", area = 3, x = 3.0, y = 47.8 }, finish = { npc = "Hierophant Theodora Mulvadania", area = 3, x = 3.0, y = 47.8 }, steps = { { name = "Fractured Elemental Shard", area = 46, x = 62.2, y = 37.3 } }, objective = "Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.  You recall Theodora mentioning the golems and elementals of that region as being a source for these shards." }, -- chain
    { id = 4062, name = "The Rise of the Machines (2/3)", level = 54, minLevel = 52, requires = { 4061 }, faction = "Horde", giver = "Hierophant Theodora Mulvadania", start = { npc = "Hierophant Theodora Mulvadania", area = 3, x = 3.0, y = 47.8 }, finish = { npc = "Lotwil Veriatus", area = 3, x = 26.0, y = 44.9 }, objective = "Take the Elemental Shard Sample to Lotwil Veriatus.  You recall Theodora saying that Lotwil was stationed in a camp to the east. " }, -- chain
    { id = 4063, name = "The Rise of the Machines (3/3)", level = 58, minLevel = 52, requires = { 4062 }, faction = "Horde", dungeon = "brd", giver = "Lotwil Veriatus", start = { npc = "Lotwil Veriatus", area = 3, x = 26.0, y = 44.9 }, finish = { npc = "Lotwil Veriatus", area = 3, x = 26.0, y = 44.9 }, steps = { { name = "Head of Argelmach", area = 1584 }, { name = "Intact Elemental Core", area = 1584 } }, objective = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic." },
    { id = 4081, name = "KILL ON SIGHT: Dark Iron Dwarves", level = 52, minLevel = 48, faction = "Horde", dungeon = "brd", finish = { npc = "Warlord Goretooth", area = 3, x = 5.8, y = 47.5 }, steps = { { name = "Anvilrage Guardsman", area = 1584 }, { name = "Anvilrage Warden", area = 1584 }, { name = "Anvilrage Footman", area = 1584 } }, objective = "Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.  " },
    { id = 4082, name = "KILL ON SIGHT: High Ranking Dark Iron Officials", level = 54, minLevel = 50, requires = { 4081 }, faction = "Horde", dungeon = "brd", finish = { npc = "Warlord Goretooth", area = 3, x = 5.8, y = 47.5 }, steps = { { name = "Anvilrage Medic", area = 1584 }, { name = "Anvilrage Soldier", area = 1584 }, { name = "Anvilrage Officer", area = 1584 } }, objective = "Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete." },
