    { id = 4121, name = "Precarious Predicament", level = 58, minLevel = 52, requires = { 4122 }, faction = "Horde", dungeon = "brd", giver = "Grark Lorkrub", start = { npc = "Grark Lorkrub", area = 46, x = 40.2, y = 34.2 }, finish = { npc = "Lexlort", area = 3, x = 5.9, y = 47.6 }, steps = { { name = "Prisoner Transport", area = 46, x = 25.7, y = 27.1 } }, objective = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.  You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.  You will also be required to hand over your Thorium Shackles to Lexlort." },
    { id = 4122, name = "Grark Lorkrub", level = 58, minLevel = 52, requires = { 4082 }, faction = "Horde", giver = "Lexlort", start = { npc = "Lexlort", area = 3, x = 5.9, y = 47.6 }, finish = { npc = "Grark Lorkrub", area = 46, x = 40.2, y = 34.2 }, objective = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.  When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody. " },
