    { id = 4810, name = "Return to Tinkee", level = 54, minLevel = 50, requires = { 4809 }, giver = "Felnok Steelspring", start = { npc = "Felnok Steelspring", area = 618, x = 61.6, y = 38.6 }, finish = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, objective = "Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes." }, -- chain
    { id = 4862, name = "En-Ay-Es-Tee-Why", level = 59, minLevel = 55, dungeon = "lbrs", giver = "Kibler", start = { npc = "Kibler", area = 46, x = 65.9, y = 21.9 }, finish = { npc = "Kibler", area = 46, x = 65.9, y = 21.9 }, steps = { { name = "Spire Spider Egg", area = 1583 } }, objective = "Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.  By the sound of it, these eggs could be found near spiders. " },
    { id = 4866, name = "Mother's Milk", level = 60, minLevel = 55, giver = "Ragged John", start = { npc = "Ragged John", area = 46, x = 65.0, y = 23.8 }, finish = { npc = "Ragged John", area = 46, x = 65.0, y = 23.8 }, steps = { { name = "Ragged John", area = 46, x = 65.0, y = 23.8 } }, objective = "In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you." },
