    { id = 4903, name = "Warlord's Command", level = 60, minLevel = 55, faction = "Horde", dungeon = "lbrs", giver = "Warlord Goretooth", start = { npc = "Warlord Goretooth", area = 3, x = 5.8, y = 47.5 }, finish = { npc = "Warlord Goretooth", area = 3, x = 5.8, y = 47.5 }, steps = { { name = "Overlord Wyrmthalak", area = 1583 }, { name = "Highlord Omokk", area = 1583 }, { name = "War Master Voone", area = 1583 }, { name = "Important Blackrock Documents", area = 1583 } }, objective = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished." },
    { id = 4907, name = "Tinkee Steamboil", level = 60, minLevel = 57, requires = { 4810 }, giver = "Felnok Steelspring", start = { npc = "Felnok Steelspring", area = 618, x = 61.6, y = 38.6 }, finish = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, objective = "Speak with Tinkee Steamboil." },
    { id = 4941, name = "Eitrigg's Wisdom", level = 60, minLevel = 55, requires = { 4903 }, faction = "Horde", giver = "Warlord Goretooth", start = { npc = "Warlord Goretooth", area = 3, x = 5.8, y = 47.5 }, finish = { npc = "Thrall", area = 1637, x = 31.7, y = 37.8 }, steps = { { name = "Council with Eitrigg.", area = 1637, x = 34.1, y = 39.3 } }, objective = "Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall.  You recall having seen Eitrigg in Thrall's chamber." }, -- chain
    { id = 4974, name = "For The Horde!", level = 60, minLevel = 55, requires = { 4941 }, faction = "Horde", dungeon = "lbrs", giver = "Thrall", start = { npc = "Thrall", area = 1637, x = 31.7, y = 37.8 }, finish = { npc = "Thrall", area = 1637, x = 31.7, y = 37.8 }, steps = { { name = "Head of Rend Blackhand", area = 1583 } }, objective = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar." },
