    { id = 5063, name = "Cap of the Scarlet Savant", level = 60, minLevel = 57, requires = { 5047 }, finish = { npc = "Malyfous Darkhammer", area = 618, x = 61.0, y = 38.8 }, steps = { { name = "Frayed Abomination Stitching", area = 2017 }, { name = "Arcane Crystal", area = 46, x = 78.8, y = 43.4 }, { name = "Enchanted Scarlet Thread", area = 2017 } }, objective = "In order to create the Cap of the Scarlet Savant, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread.   You will also be required to pay 50 gold pieces for the crafting of the item." }, -- chain
    { id = 5065, name = "The Lost Tablets of Mosh'aru", level = 58, minLevel = 40, requires = { 3528 }, giver = "Prospector Ironboot", start = { npc = "Prospector Ironboot", area = 440, x = 66.9, y = 24.0 }, finish = { npc = "Prospector Ironboot", area = 440, x = 66.9, y = 24.0 }, steps = { { name = "Third Mosh'aru Tablet", area = 139, x = 63.4, y = 7.8 }, { name = "Fourth Mosh'aru Tablet", area = 139, x = 63.8, y = 10.2 } }, objective = "Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris." }, -- chain
