    { id = 5068, name = "Breastplate of Bloodthirst", level = 60, minLevel = 57, requires = { 5047 }, finish = { npc = "Malyfous Darkhammer", area = 618, x = 61.0, y = 38.8 }, steps = { { name = "Frayed Abomination Stitching", area = 2017 }, { name = "Skin of Shadow", area = 2057 } }, objective = "In order to create the Breastplate of Bloodthirst, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 10 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Skin of Shadow.  You will also be required to pay 50 gold pieces for the crafting of the item." }, -- chain
