    { id = 5127, name = "The Demon Forge", level = 60, minLevel = 55, requires = { 5126 }, classes = 67, dungeon = "lbrs", giver = "Lorax", start = { npc = "Lorax", area = 618, x = 63.8, y = 73.8 }, finish = { npc = "Lorax", area = 618, x = 63.8, y = 73.8 }, steps = { { name = "Soul Stained Pike", area = 1583 }, { name = "Unforged Rune Covered Breastplate", area = 1583 } }, objective = "Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.  You must also find the Unforged Rune Covered Breastplate.  Return both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring." },
    { id = 5160, name = "The Matron Protectorate", level = 60, minLevel = 57, dungeon = "lbrs", giver = "Awbee", start = { npc = "Awbee" }, finish = { npc = "Haleh", area = 618, x = 54.6, y = 51.2 }, objective = "Travel to Winterspring and find Haleh. Give her Awbee's scale." },
