    { id = 6403, name = "The Great Masquerade", level = 60, minLevel = 50, requires = { 6402 }, faction = "Alliance", giver = "Reginald Windsor", start = { npc = "Reginald Windsor", area = 1519, x = 73.6, y = 91.1 }, finish = { npc = "Highlord Bolvar Fordragon", area = 1519, x = 80.2, y = 38.4 }, steps = { { name = "Reginald's March", area = 1519, x = 79.7, y = 38.8 } }, objective = "Follow Reginald Windsor through Stormwind. Protect him from harm!" }, -- chain
    { id = 6501, name = "The Dragon's Eye", level = 60, minLevel = 50, requires = { 6403 }, faction = "Alliance", giver = "Highlord Bolvar Fordragon", start = { npc = "Highlord Bolvar Fordragon", area = 1519, x = 80.2, y = 38.4 }, finish = { npc = "Haleh", area = 618, x = 54.6, y = 51.2 }, objective = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist." }, -- chain
