    { id = 6570, name = "Emberstrife", level = 60, minLevel = 55, requires = { 6569 }, faction = "Horde", giver = "Myranda the Hag", start = { npc = "Myranda the Hag", area = 28, x = 50.8, y = 77.9 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, objective = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife. " }, -- chain
    { id = 6582, name = "The Test of Skulls, Scryer", level = 60, minLevel = 55, requires = { 6570 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, steps = { { name = "The Skull of Scryer", area = 618, x = 52.7, y = 55.9 } }, objective = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.  You know that Scryer can be found in Winterspring." }, -- chain
    { id = 6583, name = "The Test of Skulls, Somnus", level = 60, minLevel = 55, requires = { 6570 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, steps = { { name = "The Skull of Somnus", area = 8, x = 76.0, y = 66.6 } }, objective = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife." }, -- chain
