    { id = 6601, name = "Ascension...", level = 60, minLevel = 55, requires = { 6585 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Rexxar", area = 405, x = 54.0, y = 2.0 }, objective = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next." }, -- chain
