    { id = 7509, name = "The Forging of Quel'Serrar", level = 60, minLevel = 60, requires = { 7508 }, classes = 3, dungeon = "ony", giver = "Lorekeeper Lydros", start = { npc = "Lorekeeper Lydros" }, finish = { npc = "Lorekeeper Lydros" }, objective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.  The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.  Do this and Quel'Serrar will be yours." },
